      'cf.brazil.near.h': 'Writing from a nearby country?',
      'cf.brazil.near': '<a href="/from-colombia" style="font-size:15px;color:var(--red);text-decoration:none">&rarr; Send a letter to Canada from Colombia</a><a href="/from-dominican-republic" style="font-size:15px;color:var(--red);text-decoration:none">&rarr; Send a letter to Canada from the Dominican Republic</a><a href="/from-el-salvador" style="font-size:15px;color:var(--red);text-decoration:none">&rarr; Send a letter to Canada from El Salvador</a><a href="/from-haiti" style="font-size:15px;color:var(--red);text-decoration:none">&rarr; Send a letter to Canada from Haiti</a><a href="/from-jamaica" style="font-size:15px;color:var(--red);text-decoration:none">&rarr; Send a letter to Canada from Jamaica</a><a href="/from-mexico" style="font-size:15px;color:var(--red);text-decoration:none">&rarr; Send a letter to Canada from Mexico</a>',
